import unittest

from solution import decode_rows


class DecodeRowsTests(unittest.TestCase):
    def test_empty_bytes(self):
        result = decode_rows(b"")
        self.assertEqual(result, [])
        self.assertIsInstance(result, list)

    def test_standard_csv_features(self):
        data = b'name,note,empty\r\nAlice,"a,b",\r\nBob,"line 1\nline 2",done\r\n'
        self.assertEqual(
            decode_rows(data),
            [
                ["name", "note", "empty"],
                ["Alice", "a,b", ""],
                ["Bob", "line 1\nline 2", "done"],
            ],
        )

    def test_custom_delimiter_and_escaped_quotes(self):
        data = b'left;"middle;value";"say ""hello"""'
        self.assertEqual(
            decode_rows(data, ";"),
            [["left", "middle;value", 'say "hello"']],
        )

    def test_one_optional_leading_bom_is_removed(self):
        bom = b"\xef\xbb\xbf"
        self.assertEqual(decode_rows(bom + b"a,b"), [["a", "b"]])
        self.assertEqual(decode_rows(bom), [])

    def test_only_first_leading_bom_is_special(self):
        bom = b"\xef\xbb\xbf"
        self.assertEqual(decode_rows(bom + bom + b"x,y"), [["\ufeffx", "y"]])
        self.assertEqual(decode_rows(b"x," + bom + b"y"), [["x", "\ufeffy"]])

    def test_malformed_utf8_raises_unicode_decode_error(self):
        for data in (b"\xff", b"a,\xc3(", b"\xef\xbb"):
            with self.subTest(data=data), self.assertRaises(UnicodeDecodeError):
                decode_rows(data)

    def test_argument_validation(self):
        for data in ("a,b", bytearray(b"a,b"), memoryview(b"a,b"), None):
            with self.subTest(data=data), self.assertRaises(TypeError):
                decode_rows(data)
        for delimiter in (b",", None, 1):
            with self.subTest(delimiter=delimiter), self.assertRaises(TypeError):
                decode_rows(b"a,b", delimiter)
        for delimiter in ("", ",,", "ab"):
            with self.subTest(delimiter=delimiter), self.assertRaises(ValueError):
                decode_rows(b"a,b", delimiter)

    def test_rows_are_separate_mutable_objects(self):
        result = decode_rows(b"a,b\na,b")
        self.assertIsNot(result[0], result[1])
        result[0].append("changed")
        self.assertEqual(result[1], ["a", "b"])
        again = decode_rows(b"a,b\na,b")
        self.assertEqual(again, [["a", "b"], ["a", "b"]])
        self.assertIsNot(result, again)


if __name__ == "__main__":
    unittest.main()

